fn is_sorted(a: &[i32]) -> bool {
    // Problem states the array is non-empty (positive size), but handle edge cases safely.
    if a.len() <= 1 {
        return true;
    }

    // Nondecreasing order means: for all k, a[k-1] <= a[k].
    // If this holds for every adjacent pair, it holds for all i < j.
    for i in 1..a.len() {
        if a[i - 1] > a[i] {
            return false;
        }
    }
    true
}